const InboxBankruptcy: React.FC<InboxBankruptcyProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 8,
  startCount = 2847,
  endCount = 2864,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const s = width / 1080; // Proportional scaling factor based on 1080px width baseline

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Counter ticking up smoothly as new emails arrive
  const currentCount = Math.floor(
    interpolate(frame, [5, 115], [startCount, endCount], { 
      extrapolateRight: 'clamp', 
      extrapolateLeft: 'clamp' 
    })
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, color: '#202124' }}>
      
      {/* Top Search Bar / Mock App Bar */}
      <div style={{
        margin: `${40 * s}px`,
        backgroundColor: '#EDEEF0',
        borderRadius: `${999 * s}px`,
        padding: `${24 * s}px ${32 * s}px`,
        display: 'flex',
        alignItems: 'center',
        gap: `${32 * s}px`
      }}>
        <MenuIcon size={48 * s} />
        <span style={{ flex: 1, fontSize: 40 * s, color: '#444746' }}>Search in mail</span>
        <div style={{ width: 64 * s, height: 64 * s, borderRadius: '50%', backgroundColor: '#8E24AA', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 28 * s, fontWeight: 'bold' }}>M</div>
      </div>

      {/* Primary & Promotions Tabs */}
      <div style={{ display: 'flex', padding: `0 ${40 * s}px`, borderBottom: `${2 * s}px solid #F1F3F4`, gap: `${60 * s}px` }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: `${16 * s}px` }}>
          <span style={{ fontSize: 36 * s, fontWeight: 'bold', color: '#0b57d0' }}>Primary ({currentCount.toLocaleString()})</span>
          <div style={{ height: 6 * s, width: '100%', backgroundColor: '#0b57d0', borderRadius: `${6 * s}px ${6 * s}px 0 0` }} />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', paddingBottom: `${22 * s}px`, gap: `${16 * s}px` }}>
          <span style={{ fontSize: 36 * s, fontWeight: '500', color: '#444746' }}>Promotions</span>
          <div style={{ backgroundColor: '#188038', color: 'white', padding: `${4 * s}px ${16 * s}px`, borderRadius: `${16 * s}px`, fontSize: 24 * s, fontWeight: 'bold' }}>342 new</div>
        </div>
      </div>

      {/* Email List Wrapper */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
        {EMAILS.map((email, i) => {
          const isArriving = email.arrivalFrame > 0;
          
          const progress = spring({
            frame: Math.max(0, frame - email.arrivalFrame),
            fps,
            config: { damping: 14, stiffness: 120 }
          });

          const rowHeightScaled = email.rowHeight * s;

          const heightVal = isArriving ? interpolate(progress, [0, 1], [0, rowHeightScaled]) : rowHeightScaled;
          const opacity = isArriving ? interpolate(progress, [0.5, 1], [0, 1], { extrapolateLeft: 'clamp' }) : 1;
          const pulse = interpolate(Math.sin((frame - email.arrivalFrame) * 0.15), [-1, 1], [0.5, 1]);

          const initialChar = email.sender[0].replace(/[^a-zA-Z]/g, 'E');

          return (
            <div key={`email-${i}`} style={{ height: heightVal, opacity, overflow: 'hidden', flexShrink: 0 }}>
              <div style={{ 
                height: rowHeightScaled, 
                display: 'flex', 
                gap: `${40 * s}px`, 
                padding: `${30 * s}px ${40 * s}px`, 
                borderBottom: `${2 * s}px solid #F1F3F4`, 
                boxSizing: 'border-box' 
              }}>
                
                {/* Avatar */}
                <div style={{ 
                  width: 100 * s, height: 100 * s, borderRadius: '50%', backgroundColor: email.avatarColor, 
                  color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', 
                  fontSize: 48 * s, fontWeight: 'bold', flexShrink: 0 
                }}>
                  {initialChar}
                </div>
                
                {/* Text Content */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
                  <span style={{ fontSize: 42 * s, fontWeight: '900', color: '#202124' }}>{email.sender}</span>
                  <span style={{ fontSize: 38 * s, fontWeight: '900', color: '#202124', marginTop: 8 * s }}>{email.subject}</span>
                  <span style={{ 
                    fontSize: 38 * s, fontWeight: '700', color: '#5F6368', marginTop: 8 * s, 
                    whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' 
                  }}>
                    {email.snippet}
                  </span>
                  {email.urgent && <UrgentBadge pulseScale={pulse} scale={s} />}
                </div>
                
                {/* Time & Action */}
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: `${24 * s}px`, flexShrink: 0 }}>
                  <span style={{ fontSize: 32 * s, fontWeight: '900', color: '#0b57d0' }}>{email.time}</span>
                  <StarIcon size={40 * s} />
                </div>

              </div>
            </div>
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

